// fayl: app/api/steps/route.ts
export async function GET() {
  const steps = ["Guruchni yuving", "Go'shtni qovuring", "Sabzi soling", "Damlang"]
  const encoder = new TextEncoder()
  const stream = new ReadableStream({
    async start(controller) {
      for (const s of steps) {
        controller.enqueue(encoder.encode(s + "\n"))
        await new Promise((r) => setTimeout(r, 50))
      }
      controller.close()
    },
  })
  return new Response(stream, { headers: { "Content-Type": "text/plain; charset=utf-8" } })
}

// fayl: app/api/events/route.ts
export async function GET() {
  const encoder = new TextEncoder()
  const stream = new ReadableStream({
    async start(c) {
      for (const status of ["qabul qilindi", "tayyorlanmoqda", "yo'lda"]) {
        c.enqueue(encoder.encode(`data: ${JSON.stringify({ status })}\n\n`))
        await new Promise((r) => setTimeout(r, 100))
      }
      c.close()
    },
  })
  return new Response(stream, { headers: { "Content-Type": "text/event-stream", "Cache-Control": "no-cache" } })
}

