"use client"
import { useEffect, useState } from "react"

export default function Tracker() {
  const [log, setLog] = useState<string[]>([])
  useEffect(() => {
    const es = new EventSource("/api/events")
    es.onmessage = (e) => setLog((l) => [...l, JSON.parse(e.data).status])
    es.onerror = () => es.close()
    return () => es.close()
  }, [])
  return <ol>{log.map((s) => <li key={s}>{s}</li>)}</ol>
}

