// fayl: app/api/health/route.ts
export const dynamic = "force-dynamic"

async function check(name: string, fn: () => Promise<unknown>) {
  const t0 = Date.now()
  try {
    await fn()
    return { name, ok: true, fast: Date.now() - t0 < 500 }
  } catch {
    return { name, ok: false }
  }
}

export async function GET() {
  const results = await Promise.all([
    check("api", () => fetch(`${process.env.API_URL}/users/1`)),
    check("cache", async () => true),
  ])
  const ok = results.every((r) => r.ok)
  return Response.json({ status: ok ? "ok" : "degraded", results }, { status: ok ? 200 : 503 })
}

