import { NextResponse } from "next/server"
import type { NextRequest } from "next/server"

export function proxy(request: NextRequest) {
    if (request.nextUrl.pathname.startsWith("/legacy/")) {
        const url = request.nextUrl.clone()
        url.pathname = url.pathname.replace("/legacy/", "/api/")
        return NextResponse.rewrite(url) // brauzerdagi URL o'zgarmaydi
    }
    const response = NextResponse.next() // so'rovni davom ettirish
    response.headers.set("x-served-by", "proxy")
    return response
}

