// fayl: app/api/subscribe/route.ts
import { NextResponse } from "next/server"

function fail(status: number, code: string, message: string) {
    return NextResponse.json({ error: { code, message } }, { status })
}

export async function POST(request: Request) {
    const type = request.headers.get("content-type") ?? ""
    if (!type.includes("application/json")) {
        return fail(415, "UNSUPPORTED_MEDIA_TYPE", "Faqat JSON qabul qilinadi")
    }
    let body: { name?: string }
    try {
        body = await request.json()
    } catch {
        return fail(400, "INVALID_JSON", "JSON noto'g'ri")
    }
    if (!body.name) return fail(422, "NAME_REQUIRED", "name maydoni majburiy")
    return NextResponse.json({ ok: true, name: body.name }, { status: 201 })
}

