import { createHmac, timingSafeEqual } from "node:crypto"

export async function POST(request: Request) {
    const raw = await request.text()
    const signature = request.headers.get("x-signature") ?? ""
    const expected = createHmac("sha256", process.env.WEBHOOK_SECRET!).update(raw).digest("hex")
    const ok = signature.length === expected.length &&
        timingSafeEqual(Buffer.from(signature), Buffer.from(expected))
    if (!ok) return Response.json({ error: "Imzo noto'g'ri" }, { status: 401 })
    const event = JSON.parse(raw)
    return Response.json({ received: true, type: event.type })
}

const ALLOWED = ["https://partner.example", "https://shop.example"]

export function corsHeaders(request: Request): Record<string, string> {
    const origin = request.headers.get("origin") ?? ""
    if (!ALLOWED.includes(origin)) return { Vary: "Origin" }
    return {
        "Access-Control-Allow-Origin": origin,
        "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type",
        Vary: "Origin",
    }
}

