// fayl: app/api/webhooks/signed/route.ts
import { createHmac, timingSafeEqual } from "node:crypto"

const TOLERANCE = 300 // soniya: 5 daqiqadan eski so'rov rad etiladi

export async function POST(request: Request) {
    const raw = await request.text()
    const header = request.headers.get("x-signature") ?? ""
    const parts = Object.fromEntries(header.split(",").map((p) => p.split("=") as [string, string]))
    const t = Number(parts.t)
    if (!t || Math.abs(Date.now() / 1000 - t) > TOLERANCE) {
        return Response.json({ error: "Imzo vaqti eskirgan" }, { status: 400 })
    }
    const expected = createHmac("sha256", process.env.WEBHOOK_SECRET!).update(`${t}.${raw}`).digest("hex")
    const valid = parts.v1?.length === expected.length && timingSafeEqual(Buffer.from(parts.v1), Buffer.from(expected))
    if (!valid) return Response.json({ error: "Imzo noto'g'ri" }, { status: 401 })
    return Response.json({ received: true })
}

