// fayl: app/api/alphabet/route.ts
const data = Buffer.from("0123456789ABCDEFGHIJ") // 20 bayt

export async function GET(request: Request) {
    const range = request.headers.get("range")
    const match = range ? /^bytes=(\d+)-(\d*)$/.exec(range) : null
    if (!match) {
        return new Response(new Uint8Array(data), {
            headers: { "Content-Type": "text/plain", "Accept-Ranges": "bytes" },
        })
    }
    const start = Number(match[1])
    const end = match[2] ? Math.min(Number(match[2]), data.length - 1) : data.length - 1
    if (start > end) {
        return new Response(null, { status: 416, headers: { "Content-Range": `bytes */${data.length}` } })
    }
    return new Response(new Uint8Array(data.subarray(start, end + 1)), {
        status: 206,
        headers: {
            "Content-Type": "text/plain",
            "Content-Range": `bytes ${start}-${end}/${data.length}`,
            "Accept-Ranges": "bytes",
        },
    })
}

