// fayl: app/api/gallery/route.ts
import { mkdir, writeFile } from "node:fs/promises"
import { tmpdir } from "node:os"
import { basename, join } from "node:path"

export async function POST(request: Request) {
    const form = await request.formData()
    const files = form.getAll("photos").filter((f): f is File => f instanceof File)
    const dir = join(tmpdir(), "oshxona-uploads")
    await mkdir(dir, { recursive: true })
    const saved: string[] = []
    for (const file of files) {
        const safeName = basename(file.name).replace(/[^a-zA-Z0-9._-]/g, "_")
        await writeFile(join(dir, safeName), Buffer.from(await file.arrayBuffer()))
        saved.push(`${safeName} (${file.size} bayt)`)
    }
    return Response.json({ count: saved.length, saved })
}

// fayl: app/api/profile/route.ts
export async function GET() {
    const upstream = await fetch(`${process.env.API_URL}/users/1`, {
        headers: { Authorization: `Bearer ${process.env.API_TOKEN}` }, // kalit serverda qoladi
    })
    if (!upstream.ok) {
        return Response.json({ error: "Tashqi xizmat xatosi" }, { status: 502 })
    }
    const user = await upstream.json()
    return Response.json({ name: user.name, city: user.city }) // id va boshqalar chiqmaydi
}

// fayl: app/api/slow-proxy/route.ts
export async function GET() {
    try {
        const res = await fetch(`${process.env.API_URL}/slow`, { signal: AbortSignal.timeout(50) })
        return Response.json(await res.json())
    } catch (e) {
        if (e instanceof DOMException && e.name === "TimeoutError") {
            return Response.json({ error: "Tashqi xizmat javob bermadi" }, { status: 504 })
        }
        throw e
    }
}

